package com.notifyme.app

import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

/** Same vectors as protocol/test_vectors.txt (generated by protocol/callsign_ref.py and checked against the mod). */
class CallsignTest {

    private fun words(name: String) =
        File("src/main/assets/$name").readLines().map { it.trim() }.filter { it.isNotEmpty() }

    @Test
    fun matchesModAndReference() {
        val cs = Callsign(words("callsign_adjectives.txt"), words("callsign_nouns.txt"))
        assertEquals("Royal Yeti 96", cs.fromPublicKey("".toByteArray()))
        assertEquals("Solid Python 43", cs.fromPublicKey("notifyme".toByteArray()))
        assertEquals("Fuzzy Hippo 39", cs.fromPublicKey("hello world".toByteArray()))
        assertEquals("Thunder Smith 52", cs.fromPublicKey("0123456789".toByteArray()))
    }
}
